<?php
use Illuminate\Support\Facades\Route; use App\Http\Controllers\{PublicController,AuthController,PostController,AdminController,InstallController};
Route::get('/install',[InstallController::class,'index']); Route::post('/install',[InstallController::class,'store']);
Route::get('/',[PublicController::class,'home']); Route::get('/news/{post:slug}',[PublicController::class,'show']); Route::get('/category/{category:slug}',[PublicController::class,'category']); Route::get('/search',[PublicController::class,'search']); Route::post('/news/{post}/like',[PublicController::class,'like'])->middleware('throttle:30,1'); Route::post('/news/{post}/comments',[PublicController::class,'comment'])->middleware('throttle:10,1');
Route::middleware('guest')->group(function(){Route::get('/login',[AuthController::class,'login']);Route::post('/login',[AuthController::class,'authenticate']);Route::get('/register',[AuthController::class,'register']);Route::post('/register',[AuthController::class,'store']);}); Route::post('/logout',[AuthController::class,'logout'])->middleware('auth');
Route::middleware('auth')->prefix('dashboard')->group(function(){Route::view('/','dashboard.index');Route::resource('posts',PostController::class)->except(['show','destroy']);});
Route::middleware(['auth','admin'])->prefix('admin')->group(function(){Route::get('/',[AdminController::class,'index']);Route::get('/posts',[AdminController::class,'posts']);Route::post('/posts/{post}/approve',[AdminController::class,'approve']);Route::post('/posts/{post}/reject',[AdminController::class,'reject']);Route::get('/categories',[AdminController::class,'categories']);Route::post('/categories',[AdminController::class,'storeCategory']);});
